{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C42"],
      "claim": "Cilomilast, a small lipophilic oral drug, had a mean absolute bioavailability of 96% (range 92-102%) in healthy humans, supporting that small lipophilic molecules can be almost completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Nevirapine absolute bioavailability was 91 ± 8% in healthy volunteers, demonstrating high oral F for a small oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Thalidomide absolute oral bioavailability was probably high (80-100%) at low doses in fasting volunteers, supporting high F for small lipophilic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Ethosuximide absolute bioavailability was 90-95% in children and adults, another small oral drug with near-complete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Bicifadine absolute bioavailability was approximately 67% in humans, above the 20% threshold, supporting positive F for a small lipophilic amine.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Memantine is a small, lipophilic adamantane amine with high permeability and minimal first-pass metabolism. Multiple small oral drugs with high absolute bioavailability support F >= 20%, and no relevant low-F evidence transfers to this scaffold. Prediction: high.",
  "evidence_gaps": [
    "No direct memantine bioavailability record is present in the evidence set.",
    "No adamantane-containing comparator is available; transferability from non-adamantane drugs is limited.",
    "Low-F comparators such as pentazocine, tranexamic acid, and rasagiline are metabolically distinct and not directly applicable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

